import * as React from "react";

export type DiceThreeIconProps = React.SVGProps<SVGSVGElement> & { size?: number };

export function DiceThreeIcon({ size = 20, ...props }: DiceThreeIconProps) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.8"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      {...props}
    >
      <rect x="5" y="5" width="14" height="14" rx="2.5" /><circle cx="9" cy="9" r="1.2" /><circle cx="12" cy="12" r="1.2" /><circle cx="15" cy="15" r="1.2" />
    </svg>
  );
}
